using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Diagnostics;using System.Management;using System.Collections.Generic;
class NativeIntegration {
 static List<string> log=new List<string>();static void Test(string name,bool result){if(!result)throw new Exception("FAIL: "+name);log.Add("PASS: "+name);Console.WriteLine(log.Last());}
 static string root;
 static void Config(ProfileStore store,Profile p){string home=Path.Combine(store.Root,p.Folder,"codex");Directory.CreateDirectory(home);Directory.CreateDirectory(Path.Combine(store.Root,p.Folder,"desktop"));File.WriteAllText(Path.Combine(home,"config.toml"),"cli_auth_credentials_store = \"file\"\nmodel = \"offline-qa\"\nmodel_provider = \"offline_qa\"\n[model_providers.offline_qa]\nname = \"QA loopback only\"\nbase_url = \"http://127.0.0.1:1/v1\"\nwire_api = \"responses\"\nrequest_max_retries = 0\nstream_max_retries = 0\n");}
 static string Auth(ProfileStore s,Profile p){return Path.Combine(s.Root,p.Folder,"codex","auth.json");}
 static Dictionary<int,DateTime> Tree(IEnumerable<int> roots){var rows=new List<Tuple<int,int>>();using(var search=new ManagementObjectSearcher("SELECT ProcessId,ParentProcessId FROM Win32_Process"))using(var list=search.Get())foreach(ManagementObject row in list)using(row)rows.Add(Tuple.Create(Convert.ToInt32(row["ProcessId"]),Convert.ToInt32(row["ParentProcessId"])));var ids=new HashSet<int>(roots);bool again=true;while(again){again=false;foreach(var row in rows)if(ids.Contains(row.Item2)&&ids.Add(row.Item1))again=true;}var result=new Dictionary<int,DateTime>();foreach(int id in ids)try{using(var p=Process.GetProcessById(id))result[id]=p.StartTime;}catch{}return result;}
 static void StopOwned(Dictionary<int,DateTime> processes){foreach(var item in processes.Reverse())try{using(var process=Process.GetProcessById(item.Key)){if(process.StartTime!=item.Value)continue;process.Kill();process.WaitForExit(3000);}}catch{}}
 static void Gui(ProfileStore store,Profile profile,string label){Config(store,profile);string auth=Auth(store,profile);Test(label+" starts signed out",!File.Exists(auth));var protectedIds=NativeApp.Running(store).Select(x=>x.Id).ToArray();var start=NativeApp.BuildStartInfo(store,profile,NativeApp.FindApp());start.WindowStyle=ProcessWindowStyle.Hidden;start.RedirectStandardOutput=true;start.RedirectStandardError=true;Process launched=null;var owned=new Dictionary<int,DateTime>();
  try{launched=new Process{StartInfo=start};launched.OutputDataReceived+=(s,e)=>{};launched.ErrorDataReceived+=(s,e)=>{};launched.Start();launched.BeginOutputReadLine();launched.BeginErrorReadLine();owned=Tree(new[]{launched.Id});bool window=false;for(int i=0;i<30;i++){Thread.Sleep(500);if(HealthService.WindowOpened(store,profile)){window=true;break;}}var matched=NativeApp.Running(store).Where(x=>x.ProfileId==profile.Id).Select(x=>x.Id).ToArray();owned=Tree(matched.Concat(new[]{launched.Id}));Test(label+" installed native GUI opens a matching window",window);Test(label+" no duplicate private state database",!Directory.GetFiles(Path.Combine(store.Root,profile.Folder,"codex"),"state_*.sqlite").Any());Test(label+" native app leaves scratch login signed out",!File.Exists(auth));
   foreach(int id in matched)try{using(var p=Process.GetProcessById(id))if(p.MainWindowHandle!=IntPtr.Zero)p.CloseMainWindow();}catch{}Thread.Sleep(1200);
  }finally{StopOwned(owned);if(launched!=null)launched.Dispose();}
  Test(label+" only scratch app processes cleaned up",!NativeApp.Running(store).Any(x=>x.ProfileId==profile.Id));Test(label+" existing user app processes untouched",protectedIds.All(id=>{try{using(var p=Process.GetProcessById(id))return !p.HasExited;}catch{return false;}}));
 }
 static int Main(string[] args){root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);try{
  var store=new ProfileStore(Path.Combine(root,"profiles"));store.State.SharedStatePath=Path.Combine(root,"common");Directory.CreateDirectory(store.State.SharedStatePath);var a=store.State.Profiles[0];var b=store.State.Profiles[1];Config(store,a);Config(store,b);var threadIds=new List<string>();string projectId="";string authA="",authB="";
  using(var rpc=new NativeRpc(store,a)){
   rpc.Call("account/login/start",new{type="apiKey",apiKey="synthetic-local-qa-A"});
   for(int i=0;i<105;i++){var response=rpc.Call("project/create",new{idempotencyKey=Guid.NewGuid().ToString(),name="Local QA project "+i,roots=new[]{new{path=root}}});if(i==0)projectId=FeatureJson.Str(FeatureJson.Obj(FeatureJson.Get(response,"project")),"id");}
   for(int i=0;i<3;i++){var response=rpc.Call("thread/start",new{cwd=root,projectId=projectId,model="offline-qa",modelProvider="offline_qa",ephemeral=false});string id=FeatureJson.Str(FeatureJson.Obj(FeatureJson.Get(response,"thread")),"id");threadIds.Add(id);rpc.Call("turn/start",new{threadId=id,input=new[]{new{type="text",text="SYNTHETIC SHARED QA MESSAGE "+i}}});Thread.Sleep(700);}
  }
  authA=BackupService.Hash(Auth(store,a));Test("A creates shared local chats and 105 projects",SharedState.Count(store.State.SharedStatePath,"threads")==3&&SharedState.Count(store.State.SharedStatePath,"projects")==105);
  using(var rpc=new NativeRpc(store,b)){
   rpc.Call("account/login/start",new{type="apiKey",apiKey="synthetic-local-qa-B"});var read=rpc.Call("thread/read",new{threadId=threadIds[0],includeTurns=true});Test("B reads original chat ID and synthetic user content",FeatureJson.Str(FeatureJson.Obj(FeatureJson.Get(read,"thread")),"id")==threadIds[0]&&FeatureJson.Json.Serialize(read).Contains("SYNTHETIC SHARED QA MESSAGE 0"));rpc.Call("thread/resume",new{threadId=threadIds[0],cwd=root});Test("B resumes exact original local chat",true);
  }
  authB=BackupService.Hash(Auth(store,b));Test("A and B credential files stay distinct",authA!=authB);Test("opening B does not replace A login",BackupService.Hash(Auth(store,a))==authA);
  using(var rpc=new NativeRpc(store,a)){var read=rpc.Call("thread/read",new{threadId=threadIds[0],includeTurns=true});Test("A return retains the same shared chat content",FeatureJson.Json.Serialize(read).Contains("SYNTHETIC SHARED QA MESSAGE 0"));rpc.Call("thread/resume",new{threadId=threadIds[0],cwd=root});}
  Test("A return does not overwrite B login",BackupService.Hash(Auth(store,b))==authB);
  var method=typeof(HealthService).GetMethod("HistoryCore",BindingFlags.NonPublic|BindingFlags.Static);var health=(HealthReport)method.Invoke(null,new object[]{store,b});Test("history verification matches IDs and paginates past 100 projects",health.Success&&health.Text.Contains("105"));File.WriteAllText(Path.Combine(root,"history-check.txt"),health.Text);
  bool guarded=false;try{HealthService.History(store,a);}catch{guarded=true;}Test("production history check respects active user-session guard",guarded);
  if(args.Length>1&&args[1]=="--backend-only"){log.Add("LIMIT: synthetic credentials only; company sign-in not tested.");return 0;}
  var guiA=store.State.Profiles[2];var guiB=store.Add("Signed-out GUI QA B");Gui(store,guiA,"GUI A");Gui(store,guiB,"GUI B");Gui(store,guiA,"GUI A return");
  log.Add("LIMIT: these are synthetic API credentials and signed-out GUI sessions, not real company ChatGPT authentication. No real model request or company sign-in was attempted.");return 0;
 }catch(Exception ex){log.Add(ex.ToString());Console.WriteLine(ex);return 1;}finally{File.WriteAllLines(Path.Combine(root,"native-integration-results.txt"),log);}}
}
